questionvariables.text:
/* Random acute angle at C between 30° and 70° */
theta : rand([47,63,57,25]);
/* Random hypotenuse length between 5 and 12 */
hyp : 5 + rand(7);  /*ensures 5 ≤ hyp ≤ 12 */

/* Horizontal side (base) x = hyp * cos(theta) */
x : hyp * cos(theta);  

/* Teacher answer */
ta:x;
